### Find Most Repeated Letters

Here is a Python function that finds the most repeated letters in a given string of lowercase letters with spaces and returns the result as a dictionary:

```python
def most_repeated_letters(s: str) -> dict:
    """
    Finds the most repeated letters in a given string of lowercase letters with spaces.

    Args:
        s (str): The input string.

    Returns:
        dict: A dictionary with the most repeated letters as keys and their frequencies as values.
    """

    # Remove spaces and count the frequency of each letter
    freq = {}
    for char in s.replace(" ", "").lower():  # Remove spaces and convert to lowercase
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    # Find the maximum frequency
    max_freq = max(freq.values())

    # Find the letters with the maximum frequency
    most_repeated = {char: count for char, count in freq.items() if count == max_freq}

    return most_repeated

# If there are multiple sets of most repeated letters, 
# this function will return all sets of most repeated letters
def most_repeated_letters_all(s: str) -> dict:
    s = s.replace(" ", "").lower()  # Remove spaces and convert to lowercase
    max_freq = max(set(s), key=s.count)  # Find the maximum frequency
    most_repeated = {char: s.count(char) for char in s if s.count(char) == s.count(max_freq)}

    return most_repeated

# Example usage:
print(most_repeated_letters("hello world"))  # Output: {'l': 3, 'o': 2}
print(most_repeated_letters("mississippi"))  # Output: {'s': 4, 'i': 4}
print(most_repeated_letters("b b b b a"))  # Output: {'b': 4}
print(most_repeated_letters_all("hello world"))  # Output: {'l': 3, 'o': 2}
print(most_repeated_letters_all("mississippi"))  # Output: {'s': 4, 'i': 4}
print(most_repeated_letters_all("b b b b a"))  # Output: {'b': 4}
```

