def brazilian_factorial(n, r):
    """
    Calculate the Brazilian factorial of n and r.

    Args:
        n (int): The input number.
        r (int): A positive integer that is less than or equal to n.

    Returns:
        int: The Brazilian factorial of n and r.
    """
    if not isinstance(n, int) or not isinstance(r, int):
        raise ValueError("Both n and r must be integers.")
    if r < 0 or r > n:
