    def construct_tree(freq_map):
        if not freq_map:
            return None
        mid = max(freq_map.keys())
        root = TreeNode(mid)
        root.left = construct_tree({k: v for k, v in freq_map.items() if k < mid})
        root.right = construct_tree({k: v for k, v in freq_map.items() if k > mid})
        return root

    root = construct_tree(freq_map)

